INSERT INTO roles (title, category, description, nco_code, esco_uri) VALUES ('Software Developer', 'ESCO Technology', 'Software developers implement or program all kinds of software systems based on specifications and designs by using programming languages, tools, and platforms.', '2512.3', 'http://data.europa.eu/esco/occupation/f2b15a0e-e65a-438a-affb-29b9d50b77d1') ON CONFLICT (title) DO NOTHING;
INSERT INTO roles (title, category, description, nco_code, esco_uri) VALUES ('Embedded Systems Software Developer', 'ESCO Technology', 'Embedded systems software developers program, implement, document and maintain software to be run on an embedded system.', '2514.2.1', 'http://data.europa.eu/esco/occupation/57af9090-55b4-4911-b2d0-86db01c00b02') ON CONFLICT (title) DO NOTHING;
INSERT INTO roles (title, category, description, nco_code, esco_uri) VALUES ('Industrial Mobile Devices Software Developer', 'ESCO Technology', 'Industrial mobile devices software developers implement applications software for specific, professional industrial mobile (handheld) devices, based on the industry needs, using general or specific development tools for device operating systems.', '2514.3', 'http://data.europa.eu/esco/occupation/bb6198c4-1d3e-40b9-9cc4-ad2dd9d7c74b') ON CONFLICT (title) DO NOTHING;
INSERT INTO roles (title, category, description, nco_code, esco_uri) VALUES ('Ict Application Developer', 'ESCO Technology', 'ICT application developers implement the ICT (software) applications based on the designs provided using application domain specific languages, tools, platforms and experience.', '2514.2', 'http://data.europa.eu/esco/occupation/bd272aee-adc9-4a06-a15c-a73b4b4a46a7') ON CONFLICT (title) DO NOTHING;
INSERT INTO roles (title, category, description, nco_code, esco_uri) VALUES ('Embedded System Designer', 'ESCO Technology', 'Embedded system designers translate and design requirements and the high-level plan or architecture of an embedded control system according to technical software specifications.', '2511.4', 'http://data.europa.eu/esco/occupation/10469d70-78a3-4650-9e29-d04de13c62c1') ON CONFLICT (title) DO NOTHING;
INSERT INTO roles (title, category, description, nco_code, esco_uri) VALUES ('Data Scientist', 'ESCO Technology', 'Data scientists find and interpret rich data sources, manage large amounts of data, merge data sources, ensure consistency of data-sets, and create visualisations to aid in understanding data. They build mathematical models using data, present and communicate data insights and findings to specialist', '2511.3', 'http://data.europa.eu/esco/occupation/258e46f9-0075-4a2e-adae-1ff0477e0f30') ON CONFLICT (title) DO NOTHING;
INSERT INTO roles (title, category, description, nco_code, esco_uri) VALUES ('Bioinformatics Scientist', 'ESCO Technology', 'Bioinformatics scientists analyse biological processes using computer programmes. They maintain or construct databases containing biological information. Bioinformatics scientists gather and analyse biological data and may also assist scientists in various fields, including in biotechnology and phar', '2131.3', 'http://data.europa.eu/esco/occupation/68d973df-bf10-4bf7-9a1b-fbd9f604b9db') ON CONFLICT (title) DO NOTHING;
INSERT INTO roles (title, category, description, nco_code, esco_uri) VALUES ('Cosmologist', 'ESCO Technology', 'Cosmologists focus on the study of the universe as a whole, which is made up by its origin, evolution and ultimate fate. They use tools and scientific instruments to observe and study other galaxies and astronomical objects such as stars, black holes, planets and other celestial bodies.', '2111.2', 'http://data.europa.eu/esco/occupation/bc659adc-f42c-4ef6-89fe-fd030033f446') ON CONFLICT (title) DO NOTHING;
INSERT INTO roles (title, category, description, nco_code, esco_uri) VALUES ('Sensory Scientist', 'ESCO Technology', 'Sensory scientists carry out sensory analysis in order to compose or improve flavours and fragrances for the food, beverage and cosmetics industry. They base their flavour and fragrance development on sensory and consumer research. Sensory scientists carry out research and analyse statistical data t', '2113.2', 'http://data.europa.eu/esco/occupation/8606c0fd-c7cb-404d-887f-3a30ef7a81b4') ON CONFLICT (title) DO NOTHING;
INSERT INTO roles (title, category, description, nco_code, esco_uri) VALUES ('Meteorologist', 'ESCO Technology', 'Meteorologists study climate processes, measure and predict weather patterns and provide consultancy services to a variety of weather information users. They work out models for weather forecasting, develop instruments to collect meteorological data and compile statistics and databases.', '2112.1', 'http://data.europa.eu/esco/occupation/1c862e14-80f8-4aa8-8f1c-fd2ca95b63ad') ON CONFLICT (title) DO NOTHING;
INSERT INTO roles (title, category, description, nco_code, esco_uri) VALUES ('Web Developer', 'ESCO Technology', 'Web developers develop, implement and document web-accessible software based on the designs provided. They align the client''s web presence with its business strategy, troubleshoot software problems and issues and look for ways to improve the application.', '2513.5', 'http://data.europa.eu/esco/occupation/c40a2919-48a9-40ea-b506-1f34f693496d') ON CONFLICT (title) DO NOTHING;
INSERT INTO roles (title, category, description, nco_code, esco_uri) VALUES ('Property Developer', 'ESCO Technology', 'Property developers buy land, finance deals, order construction projects and orchestrate the process of development. They purchase a tract of land, decide on a marketing strategy, and develop the building program. Developers must also obtain legal approval and financing. When the project is finished', '1323.1.2', 'http://data.europa.eu/esco/occupation/b9711647-463f-4991-a858-d5de66ff2f83') ON CONFLICT (title) DO NOTHING;
INSERT INTO roles (title, category, description, nco_code, esco_uri) VALUES ('User Interface Developer', 'ESCO Technology', 'User interface developers implement, code, document and maintain the interface of a software system by using front-end development technologies.', '2512.4', 'http://data.europa.eu/esco/occupation/866c7813-2c03-47d7-9bdc-192cfbace57c') ON CONFLICT (title) DO NOTHING;
INSERT INTO roles (title, category, description, nco_code, esco_uri) VALUES ('Ict System Developer', 'ESCO Technology', 'ICT system developers maintain, audit and improve organisational support systems. They use existing or new technologies to meet particular needs. They test both hardware and software system components, diagnose and resolve system faults.', '2511.14', 'http://data.europa.eu/esco/occupation/a7c1d23d-aeca-4bee-9a08-5993ed98b135') ON CONFLICT (title) DO NOTHING;
INSERT INTO roles (title, category, description, nco_code, esco_uri) VALUES ('Ict System Analyst', 'ESCO Technology', 'ICT system analysts specify the system needs to meet the end user requirements. They analyse system functions in order to define their goals or purposes and to discover operations and procedures for accomplishing them most efficiently. They also design new IT solutions to improve business efficiency', '2511.12', 'http://data.europa.eu/esco/occupation/a6a0b60f-08da-4faa-bf54-942987efb471') ON CONFLICT (title) DO NOTHING;
INSERT INTO roles (title, category, description, nco_code, esco_uri) VALUES ('Accounting Analyst', 'ESCO Technology', 'Accounting analysts evaluate the financial statements of clients, usually companies, which include the income sheet, the balance sheet, the statement of cash flows and additional notes to other financial statements. They interpret and implement new accounting systems and accounting procedures and wi', '2411.1.1', 'http://data.europa.eu/esco/occupation/caafca69-9faa-4850-8930-a3fa07fea4e6') ON CONFLICT (title) DO NOTHING;
INSERT INTO roles (title, category, description, nco_code, esco_uri) VALUES ('Financial Auditor', 'ESCO Technology', 'Financial auditors collect and examine financial data for clients, organisations and companies. They ensure the financial data is properly maintained and free of material misstatements due to error or fraud, that it adds up, and functions legally and effectively. They review lending and credit polic', '2411.1.7', 'http://data.europa.eu/esco/occupation/1ad59946-d13e-441e-9b36-56e1df055e21') ON CONFLICT (title) DO NOTHING;
INSERT INTO roles (title, category, description, nco_code, esco_uri) VALUES ('Picture Archiving And Communication Systems Administrator', 'ESCO Technology', 'Picture archiving and communication systems administrators manage picture archiving and communication systems (PACS). They store images taken by various types of medical equipment, such as X-rays, in order to enable easy access to these images for medical. PACS administrators ensure the day-to-day m', '3252.3', 'http://data.europa.eu/esco/occupation/32ac76f6-20a0-469e-8cac-e68634087dd3') ON CONFLICT (title) DO NOTHING;
INSERT INTO roles (title, category, description, nco_code, esco_uri) VALUES ('Telecommunications Analyst', 'ESCO Technology', 'Telecommunications analysts review, analyse and evaluate an organisation''s telecommunications needs and systems. They provide training on the telecommunications system features and functionalities.', '2153.1.1', 'http://data.europa.eu/esco/occupation/c5d36eef-df20-47a8-a332-5b4358fa83e3') ON CONFLICT (title) DO NOTHING;
INSERT INTO roles (title, category, description, nco_code, esco_uri) VALUES ('Database Administrator', 'ESCO Technology', 'Database administrators test, implement and administer computer databases. They use their expertise in database management systems to plan, coordinate and implement security measures to safeguard computer databases. They also use scripts and configuration files to tailor a database to users'' needs.', '2521.1', 'http://data.europa.eu/esco/occupation/8c57af09-719c-42b3-be40-6ed4946236cc') ON CONFLICT (title) DO NOTHING;
INSERT INTO roles (title, category, description, nco_code, esco_uri) VALUES ('Secretary', 'ESCO Technology', '
INSERT INTO roles (title, category, description, nco_code, esco_uri) VALUES ('Database Developer', 'ESCO Technology', 'Database developers program, implement and coordinate changes to computer databases based on their expertise of database management systems.', '2521.3', 'http://data.europa.eu/esco/occupation/b11e1742-5e28-4270-b081-b0193d85ee7d') ON CONFLICT (title) DO NOTHING;
INSERT INTO roles (title, category, description, nco_code, esco_uri) VALUES ('Ict Security Administrator', 'ESCO Technology', 'ICT security administrators plan and carry out security measures to protect information and data from unauthorised access, deliberate attack, theft and corruption.', '2529.5', 'http://data.europa.eu/esco/occupation/0464b062-cea6-4164-b10d-956c61956ae7') ON CONFLICT (title) DO NOTHING;
INSERT INTO roles (title, category, description, nco_code, esco_uri) VALUES ('Database Integrator', 'ESCO Technology', 'Database integrators perform integration among different databases. They maintain integration and ensure interoperability.', '2521.4', 'http://data.europa.eu/esco/occupation/3d190639-90f8-4402-b1b3-a104a17e0d67') ON CONFLICT (title) DO NOTHING;
INSERT INTO roles (title, category, description, nco_code, esco_uri) VALUES ('Computer Hardware Engineer', 'ESCO Technology', 'Computer hardware engineers design and develop computer hardware systems and components, such as circuit boards, modems, and printers. They draught blueprints and assembly drawings, develop and test the prototypes, and supervise the production process.', '2152.1.1', 'http://data.europa.eu/esco/occupation/92bb3d8c-8a9f-4cd7-80ec-247bbf173004') ON CONFLICT (title) DO NOTHING;
INSERT INTO roles (title, category, description, nco_code, esco_uri) VALUES ('Ict Network Engineer', 'ESCO Technology', 'ICT network engineers implement, maintain and support computer networks. They also perform network modelling, analysis, and planning. They may also design network and computer security measures. They may research and recommend network and data communications hardware and software.', '2523.3', 'http://data.europa.eu/esco/occupation/cf2b03cd-feb7-4f47-90f6-ff1ed6016d3d') ON CONFLICT (title) DO NOTHING;
INSERT INTO roles (title, category, description, nco_code, esco_uri) VALUES ('Ict Network Administrator', 'ESCO Technology', 'ICT network administrators maintain operation of a reliable, secure, and efficient data communications network, including LAN, WAN, intranet, and internet. They perform network address assignment, management and implementation of routing protocols such as ISIS, OSPF, BGP, routing table configuration', '2522.1.1', 'http://data.europa.eu/esco/occupation/81480b40-a318-47f3-9b2c-56b69ed67d95') ON CONFLICT (title) DO NOTHING;
INSERT INTO roles (title, category, description, nco_code, esco_uri) VALUES ('Ict System Administrator', 'ESCO Technology', 'ICT system administrators are responsible for the upkeep, configuration, and reliable operation of computer and network systems, servers, workstations and peripheral devices. They may acquire, install, or upgrade computer components and software; automate routine tasks; write computer programs; trou', '2522.1', 'http://data.europa.eu/esco/occupation/9e2e6e1e-363b-4e1b-a673-7bc0f7343300') ON CONFLICT (title) DO NOTHING;
INSERT INTO roles (title, category, description, nco_code, esco_uri) VALUES ('Ict Network Technician', 'ESCO Technology', 'ICT network technicians install, maintain and troubleshoot networks, data communications equipment and network installed devices such as printers and storage area networks. They also analyse and fix network-related problems reported by users.', '3513.2', 'http://data.europa.eu/esco/occupation/64c7d461-152c-477f-a8e2-c2c537e9d617') ON CONFLICT (title) DO NOTHING;
INSERT INTO roles (title, category, description, nco_code, esco_uri) VALUES ('Ict Security Manager', 'ESCO Technology', 'ICT security managers propose and implement necessary security updates. They advise, support, inform and provide training and security awareness and take direct action on all or part of a network or system.
INSERT INTO roles (title, category, description, nco_code, esco_uri) VALUES ('Chief Ict Security Officer', 'ESCO Technology', 'Chief ICT security officers protect company and employee information against unauthorized access. They also define the Information System security policy, manage security deployment across all Information Systems and ensure the provision of information availability.', '2529.1', 'http://data.europa.eu/esco/occupation/276ba420-ef09-4a0e-b215-2c2e2f80ad28') ON CONFLICT (title) DO NOTHING;
INSERT INTO roles (title, category, description, nco_code, esco_uri) VALUES ('Ict Security Consultant', 'ESCO Technology', 'ICT security consultants advise and implement solutions to control access to data and programs. They promote a safe exchange of information.
INSERT INTO roles (title, category, description, nco_code, esco_uri) VALUES ('Ict Intelligent Systems Designer', 'ESCO Technology', 'ICT intelligent systems designers apply methods of artificial intelligence in engineering, robotics and computer science to design programs which simulate intelligence including thinking models, cognitive and knowledge-based systems, problem solving, and decision making. They also integrate structur', '2511.10', 'http://data.europa.eu/esco/occupation/35553663-deab-4d9a-bf22-15c1625d28e8') ON CONFLICT (title) DO NOTHING;
INSERT INTO roles (title, category, description, nco_code, esco_uri) VALUES ('E-Learning Developer', 'ESCO Technology', 'E-learning developers design and develop simpler forms of digital learning content including reference materials, slides, assessments, screen-casts, interview videos and podcasts. They write and provide content for a computer based learning application.', '2359.5', 'http://data.europa.eu/esco/occupation/ec5b72d1-0206-4179-9abd-570c66bc44b9') ON CONFLICT (title) DO NOTHING;
INSERT INTO roles (title, category, description, nco_code, esco_uri) VALUES ('Learning Support Teacher', 'ESCO Technology', 'Learning support teachers assist students who have general learning difficulties. Learning support teachers focus on basic skills such as numeracy and literacy and thus teach basic subjects such as writing, reading, math and languages and they work for an educational institution such as a primary or', '2352.1.3', 'http://data.europa.eu/esco/occupation/114c5a6c-1869-4a67-8ec0-660ec303f8cc') ON CONFLICT (title) DO NOTHING;
INSERT INTO roles (title, category, description, nco_code, esco_uri) VALUES ('Leather Production Machine Operator', 'ESCO Technology', 'Leather production machine operators use the tannery machinery and programs according to the specific requirements to achieve the department''s standards. They do routine maintenance of the machinery.', '8155.1', 'http://data.europa.eu/esco/occupation/3da8ee8c-ab60-4feb-ab5b-3ba31ef9ec1f') ON CONFLICT (title) DO NOTHING;
INSERT INTO roles (title, category, description, nco_code, esco_uri) VALUES ('Digital Games Developer', 'ESCO Technology', 'Digital games developers program, implement and document digital games. They implement technical standards in gameplay, graphics, sound and functionality.', '2513.1', 'http://data.europa.eu/esco/occupation/9ebaf3f0-0be0-47b7-b2b1-b3b04130fa81') ON CONFLICT (title) DO NOTHING;
INSERT INTO roles (title, category, description, nco_code, esco_uri) VALUES ('Digital Games Designer', 'ESCO Technology', 'Digital games designers develop the layout, logic, concept and gameplay of a digital game. They focus on playfield design, specification writing, and entry of numeric properties that balance and tune the gameplay.', '2166.7', 'http://data.europa.eu/esco/occupation/d68ff35f-e34d-4e32-88ab-d6c06a6c25b9') ON CONFLICT (title) DO NOTHING;
INSERT INTO roles (title, category, description, nco_code, esco_uri) VALUES ('Digital Games Tester', 'ESCO Technology', 'Digital games testers review and test various genres of digital games by playing them in order to find bugs and glitches within the game''s functionality or graphics. They may evaluate the capacity of attraction and playability of games. They may also debug the games themselves.', '2519.6.1', 'http://data.europa.eu/esco/occupation/33e4f026-a823-4ffc-99e4-60d3fe597a1e') ON CONFLICT (title) DO NOTHING;
INSERT INTO roles (title, category, description, nco_code, esco_uri) VALUES ('Gambling, Betting, And Lottery Game Developer', 'ESCO Technology', 'Gambling, betting, and lottery game developers create, develop and produce content for new lottery and similar games for large audiences.', '2120.3', 'http://data.europa.eu/esco/occupation/18552245-3c36-4a52-b4c6-295cabb5c93b') ON CONFLICT (title) DO NOTHING;
INSERT INTO roles (title, category, description, nco_code, esco_uri) VALUES ('Digital Artist', 'ESCO Technology', 'Digital artists create art which applies digital technology as an essential part of the creative process. Digital art is usually created using computers or more specialised digital equipment. It may be enjoyed using the same instruments, shared over the internet, or presented using more traditional ', '2166.6', 'http://data.europa.eu/esco/occupation/d5c4ab26-c293-4f4d-ad89-fe776f49a67f') ON CONFLICT (title) DO NOTHING;
INSERT INTO roles (title, category, description, nco_code, esco_uri) VALUES ('Circus Artist', 'ESCO Technology', 'Circus artists develop original performance pieces showcasing great artistic and performing skills, emotive depth and artistic proposals for the general public. Alone, or collectively, they may perform one or more traditional or original circus disciplines, which are usually based on physical capabi', '2659.2.1', 'http://data.europa.eu/esco/occupation/22799921-76a1-44c4-a7c3-c6a548e8ad85') ON CONFLICT (title) DO NOTHING;
